            accept: [['^(however|even so|yet|nevertheless|nonetheless|that said|on the other hand)$']],
            reject: [{ re: '^(therefore|thus|so|as a result|consequently)$', hint: 'That shows a result. The next sentence goes against the idea.' },
              { re: '^(moreover|furthermore|in addition|also|besides)$', hint: 'That adds a similar point. The next sentence goes against it.' },
              { re: '^(for example|for instance)$', hint: 'You already gave your example.' },
              { re: '^but$', hint: 'In an essay, start this sentence with a contrast linker and a comma.' }],
